import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    try:
        response = requests.get(webpage_url, verify=False)
        response.raise_for_status()
    except requests.RequestException as e:
        raise requests.RequestException(f"Network issue: {e}")

    tree = html.fromstring(response.content)
    table_elements = tree.xpath('//table')
    if not table_elements:
        return 0

    table = table_elements[0]
    headers = []
    header_elements = table.xpath('.//th')
    for header in header_elements:
        headers.append(header.text_content().strip())

    rows = []
    for row in table.xpath('.//tr'):
        cells = row.xpath('.//td')
        if cells:
            row_data = [cell.text_content().strip() for cell in cells]
            rows.append(row_data)

    if not rows:
        return 0

    df = pd.DataFrame(rows, columns=headers if headers else None)

    try:
        conn = sqlite3.connect(database_name)
        df.to_sql('my_table', conn, if_exists='replace', index=False)
        conn.close()
    except sqlite3.DatabaseError as e:
        raise sqlite3.DatabaseError(f"Database issue: {e}")

    return len(rows)

import json
import requests
import chardet
def task_func(url="http://api.example.com/data", from_encoding=None, to_encoding="utf8"):
    try:
        response = requests.get(url, timeout=5)
        response.raise_for_status()
    except requests.RequestException as e:
        raise ConnectionError(f"Failed to fetch data from {url}: {e}")

    content = response.content
    if not content:
        return {}

    if from_encoding is None:
        detected = chardet.detect(content)
        if detected['confidence'] > 0.5:
            from_encoding = detected['encoding']
        else:
            raise ValueError("Unable to detect encoding for non-empty content")

    try:
        decoded_content = content.decode(from_encoding)
        re_encoded_content = decoded_content.encode(to_encoding)
        parsed_data = json.loads(re_encoded_content)
    except (UnicodeDecodeError, UnicodeEncodeError, json.JSONDecodeError) as e:
        raise ValueError(f"Error processing content: {e}")

    return parsed_data

