def task_func(url):
    try:
        response = requests.get(url, verify=False)
        response.raise_for_status()
    except:
        return []
    soup = BeautifulSoup(response.text, 'html.parser')
    scripts = soup.find_all('script')
    result = []
    for script in scripts:
        try:
            content = script.string
            if content:
                parsed = ast.literal_eval(content.strip())
                if isinstance(parsed, dict):
                    result.append(parsed)
        except:
            continue
    return result

import requests
import logging
def task_func(repo_url: str) -> dict:
    if not repo_url or not isinstance(repo_url, str):
        raise ValueError("Invalid repository URL provided.")

    headers = {'Accept': 'application/vnd.github.v3+json'}
    try:
        response = requests.get(repo_url, headers=headers, verify=False)
        if response.status_code == 403:
            raise requests.exceptions.HTTPError("GitHub API rate limit exceeded.")
        response.raise_for_status()
        repo_info = response.json()
        if repo_info.get('open_issues_count', 0) > 1000:
            logging.warning(f"Repository {repo_info.get('full_name', 'unknown')} has over 1000 open issues.")
        return repo_info
    except requests.exceptions.HTTPError as e:
        raise e
    except requests.exceptions.RequestException as e:
        raise requests.exceptions.RequestException(f"Request failed: {e}")

